CREATE OR REPLACE FUNCTION radar.consume_github_oidc_jti_v1(p_jti text, p_expires_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  inserted_jti text;
begin
  if p_jti is null or btrim(p_jti) = '' then
    raise exception 'OIDC_JTI_REQUIRED' using errcode = '22023';
  end if;
  if p_expires_at is null then
    raise exception 'OIDC_EXP_REQUIRED' using errcode = '22023';
  end if;
  if p_expires_at <= clock_timestamp() then
    raise exception 'OIDC_JTI_EXPIRED' using errcode = '22023';
  end if;

  -- JWT verification rejects expired tokens before this RPC. Rows that can no
  -- longer correspond to an accepted token therefore carry no replay value.
  delete from radar.github_oidc_replay_guard
  where expires_at <= clock_timestamp();

  insert into radar.github_oidc_replay_guard(jti, expires_at)
  values (btrim(p_jti), p_expires_at)
  on conflict (jti) do nothing
  returning jti into inserted_jti;

  if inserted_jti is null then
    return 'REPLAY';
  end if;
  return 'CONSUMED';
end;
$function$

CREATE OR REPLACE FUNCTION radar.mark_stale_nodes_offline(p_stale_after interval DEFAULT '00:05:00'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  changed integer;
begin
  if p_stale_after is null or p_stale_after <= interval '0 seconds' then
    raise exception 'RADAR_INVALID_STALE_INTERVAL' using errcode = '22023';
  end if;

  update radar.nodes
  set status = 'OFFLINE', updated_at = now()
  where status in ('ONLINE','IDLE','WORKING','WAITING_DEPENDENCY','DEGRADED')
    and (
      last_heartbeat is null
      or lease_expires_at is null
      or lease_expires_at <= now()
      or last_heartbeat < now() - p_stale_after
    );
  get diagnostics changed = row_count;
  return changed;
end;
$function$

CREATE OR REPLACE FUNCTION radar.prevent_dependency_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
begin
  if exists (
    with recursive reachable(id) as (
      select new.successor_assignment_id
      union
      select d.successor_assignment_id
      from radar.dependencies d
      join reachable r on d.predecessor_assignment_id = r.id
      where d.active
    )
    select 1 from reachable where id = new.predecessor_assignment_id
  ) then
    raise exception 'RADAR_DEPENDENCY_CYCLE' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION radar.prevent_node_identity_reassignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
begin
  if new.identity_id is distinct from old.identity_id then
    raise exception 'RADAR_NODE_IDENTITY_IMMUTABLE' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_claim_batch_v1(p_identity_id text, p_branch text, p_expected_projected_head_sha text, p_target_head_sha text, p_control_sha text, p_topology_sha text, p_files text[], p_claim_owner text, p_lease_seconds integer DEFAULT 300)
 RETURNS radar.projection_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  lane radar.projection_lane_state;
  active_batch radar.projection_batches;
  result radar.projection_batches;
  file_path text;
begin
  if p_target_head_sha is null or p_target_head_sha !~ '^[0-9a-f]{40}$'
     or (p_expected_projected_head_sha is not null
         and p_expected_projected_head_sha !~ '^[0-9a-f]{40}$') then
    raise exception 'RADAR_PROJECTION_HEAD_INVALID' using errcode = '22023';
  end if;
  if p_claim_owner is null or btrim(p_claim_owner) = ''
     or p_control_sha is null or p_control_sha !~ '^[0-9a-f]{40}$'
     or p_topology_sha is null or p_topology_sha !~ '^[0-9a-f]{40}$'
     or p_lease_seconds is null or p_lease_seconds <= 0 then
    raise exception 'RADAR_PROJECTION_CLAIM_INVALID' using errcode = '22023';
  end if;
  if p_files is null then
    p_files := array[]::text[];
  end if;
  if exists (
    select 1 from unnest(p_files) f
    where f is null or btrim(f) = ''
  ) or cardinality(p_files) <> (select count(distinct f) from unnest(p_files) f) then
    raise exception 'RADAR_PROJECTION_FILES_INVALID' using errcode = '22023';
  end if;

  select * into lane
  from radar.projection_lane_state
  where identity_id = p_identity_id and branch = p_branch
  for update;

  if lane.identity_id is null then
    raise exception 'RADAR_PROJECTION_LANE_UNSEEDED' using errcode = '23514';
  end if;
  if lane.projected_head_sha is distinct from p_expected_projected_head_sha then
    raise exception 'RADAR_PROJECTION_BASE_CHANGED' using errcode = '40001';
  end if;
  if lane.control_sha is distinct from p_control_sha
     or lane.topology_sha is distinct from p_topology_sha then
    raise exception 'RADAR_PROJECTION_CONTROL_CUT_CHANGED' using errcode = '40001';
  end if;

  select * into active_batch
  from radar.projection_batches
  where identity_id = p_identity_id
    and branch = p_branch
    and status = 'CLAIMED'
  for update;

  if active_batch.batch_id is not null then
    if active_batch.claim_expires_at > now() then
      raise exception 'RADAR_PROJECTION_CLAIM_BUSY' using errcode = '55P03';
    end if;
    update radar.projection_batches
    set status = 'STALE', updated_at = now()
    where batch_id = active_batch.batch_id;
  end if;

  insert into radar.projection_batches(
    identity_id, branch, expected_projected_head_sha, target_head_sha,
    control_sha, topology_sha, claim_owner, claim_expires_at
  ) values (
    p_identity_id, p_branch, p_expected_projected_head_sha, p_target_head_sha,
    p_control_sha, p_topology_sha, p_claim_owner,
    now() + make_interval(secs => p_lease_seconds)
  ) returning * into result;

  foreach file_path in array p_files loop
    insert into radar.projection_batch_files(batch_id, path)
    values (result.batch_id, file_path);
  end loop;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_finalize_batch_v1(p_batch_id uuid, p_claim_token uuid)
 RETURNS radar.projection_lane_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  lane_key_identity text;
  lane_key_branch text;
  batch radar.projection_batches;
  lane radar.projection_lane_state;
  result radar.projection_lane_state;
begin
  select identity_id, branch
    into lane_key_identity, lane_key_branch
  from radar.projection_batches
  where batch_id = p_batch_id;

  if lane_key_identity is null then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;

  select * into lane
  from radar.projection_lane_state
  where identity_id = lane_key_identity
    and branch = lane_key_branch
  for update;

  if lane.identity_id is null then
    raise exception 'RADAR_PROJECTION_LANE_UNKNOWN' using errcode = 'P0002';
  end if;

  select * into batch
  from radar.projection_batches
  where batch_id = p_batch_id
  for update;

  if batch.batch_id is null
     or batch.identity_id <> lane_key_identity
     or batch.branch <> lane_key_branch
     or batch.claim_token <> p_claim_token then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;

  if batch.status = 'COMPLETE' then
    if lane.projected_head_sha is distinct from batch.target_head_sha then
      raise exception 'RADAR_PROJECTION_COMPLETE_CURSOR_MISMATCH' using errcode = 'XX000';
    end if;
    return lane;
  end if;

  if batch.status <> 'CLAIMED' or batch.claim_expires_at <= now() then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;
  if lane.projected_head_sha is distinct from batch.expected_projected_head_sha then
    raise exception 'RADAR_PROJECTION_BASE_CHANGED' using errcode = '40001';
  end if;
  if lane.control_sha is distinct from batch.control_sha
     or lane.topology_sha is distinct from batch.topology_sha then
    raise exception 'RADAR_PROJECTION_CONTROL_CUT_CHANGED' using errcode = '40001';
  end if;
  if exists (
    select 1 from radar.projection_batch_files
    where batch_id = batch.batch_id
      and state not in ('PROJECTED','IDEMPOTENT')
  ) then
    raise exception 'RADAR_PROJECTION_UNRESOLVED_FILES' using errcode = '23514';
  end if;

  update radar.projection_lane_state
  set projected_head_sha = batch.target_head_sha,
      updated_at = now()
  where identity_id = batch.identity_id and branch = batch.branch
  returning * into result;

  update radar.projection_batches
  set status = 'COMPLETE', completed_at = now(), updated_at = now()
  where batch_id = batch.batch_id;

  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_project_file_v1(p_batch_id uuid, p_claim_token uuid, p_path text, p_message_id text, p_created_at timestamp with time zone, p_sender text, p_audience text[], p_requires_ack boolean, p_source_refs text[], p_content_hash text, p_idempotency_key text, p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  lane_key_identity text;
  lane_key_branch text;
  lane radar.projection_lane_state;
  batch radar.projection_batches;
  current_file radar.projection_batch_files;
  projection_result text;
  terminal_state text;
begin
  if p_batch_id is null
     or p_claim_token is null
     or p_path is null
     or btrim(p_path) = '' then
    raise exception 'RADAR_PROJECTION_FILE_REQUEST_INVALID' using errcode = '22023';
  end if;

  -- This first read discovers the lane key only. It grants no authority. The
  -- batch is re-read and fully revalidated after the lane lock is held.
  select identity_id, branch
    into lane_key_identity, lane_key_branch
  from radar.projection_batches
  where batch_id = p_batch_id;

  if lane_key_identity is null then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;

  select * into lane
  from radar.projection_lane_state
  where identity_id = lane_key_identity
    and branch = lane_key_branch
  for update;

  if lane.identity_id is null then
    raise exception 'RADAR_PROJECTION_LANE_UNKNOWN' using errcode = 'P0002';
  end if;

  select * into batch
  from radar.projection_batches
  where batch_id = p_batch_id
  for update;

  if batch.batch_id is null
     or batch.identity_id <> lane_key_identity
     or batch.branch <> lane_key_branch
     or batch.claim_token <> p_claim_token
     or batch.status <> 'CLAIMED'
     or batch.claim_expires_at <= now() then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;

  if lane.projected_head_sha is distinct from batch.expected_projected_head_sha then
    raise exception 'RADAR_PROJECTION_BASE_CHANGED' using errcode = '40001';
  end if;
  if lane.control_sha is distinct from batch.control_sha
     or lane.topology_sha is distinct from batch.topology_sha then
    raise exception 'RADAR_PROJECTION_CONTROL_CUT_CHANGED' using errcode = '40001';
  end if;

  select * into current_file
  from radar.projection_batch_files
  where batch_id = p_batch_id and path = p_path
  for update;

  if current_file.path is null then
    raise exception 'RADAR_PROJECTION_FILE_UNKNOWN' using errcode = 'P0002';
  end if;

  if current_file.state in ('PROJECTED', 'IDEMPOTENT') then
    if current_file.result_ref is null
       or not (
         current_file.result_ref in ('INSERTED', 'IDEMPOTENT')
         or current_file.result_ref ~ '^CONFLICT_INSERTED:.+$'
         or current_file.result_ref ~ '^CONFLICT_IDEMPOTENT:.+$'
       ) then
      raise exception 'RADAR_PROJECTION_FILE_RESULT_CORRUPT' using errcode = 'XX000';
    end if;
    return current_file.result_ref;
  end if;

  if current_file.state <> 'PENDING' then
    raise exception 'RADAR_PROJECTION_FILE_NOT_PROJECTABLE' using errcode = '23514';
  end if;

  -- Bind the provider message mutation to the exact claimed lane/path/target.
  if p_sender is null or lower(btrim(p_sender)) <> batch.identity_id then
    raise exception 'RADAR_PROJECTION_SENDER_MISMATCH' using errcode = '23514';
  end if;
  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload->>'admitted_lane_identity' is distinct from batch.identity_id
     or p_payload->>'source_path' is distinct from p_path
     or p_payload->>'source_branch_head' is distinct from batch.target_head_sha then
    raise exception 'RADAR_PROJECTION_SOURCE_BINDING_MISMATCH' using errcode = '23514';
  end if;

  projection_result := radar.project_bus_message_v1(
    p_message_id,
    p_created_at,
    p_sender,
    p_audience,
    p_requires_ack,
    p_source_refs,
    p_content_hash,
    p_idempotency_key,
    p_payload
  );

  if projection_result = 'INSERTED'
     or projection_result ~ '^CONFLICT_INSERTED:.+$' then
    terminal_state := 'PROJECTED';
  elsif projection_result = 'IDEMPOTENT'
     or projection_result ~ '^CONFLICT_IDEMPOTENT:.+$' then
    terminal_state := 'IDEMPOTENT';
  else
    -- Because this function is one transaction, an unknown result rolls back
    -- any message/reconciliation mutation performed above.
    raise exception 'RADAR_PROJECTION_RESULT_INVALID' using errcode = 'XX000';
  end if;

  update radar.projection_batch_files
  set state = terminal_state,
      result_ref = projection_result,
      updated_at = now()
  where batch_id = p_batch_id
    and path = p_path
    and state = 'PENDING';

  if not found then
    raise exception 'RADAR_PROJECTION_FILE_STATE_RACE' using errcode = '40001';
  end if;

  return projection_result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_record_file_result_v1(p_batch_id uuid, p_claim_token uuid, p_path text, p_state text, p_result_ref text DEFAULT NULL::text)
 RETURNS radar.projection_batch_files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  batch radar.projection_batches;
  current_file radar.projection_batch_files;
  result radar.projection_batch_files;
begin
  if p_state not in ('PROJECTED','IDEMPOTENT','FAILED','CONFLICT') then
    raise exception 'RADAR_PROJECTION_FILE_STATE_INVALID' using errcode = '22023';
  end if;

  select * into batch
  from radar.projection_batches
  where batch_id = p_batch_id
  for update;

  if batch.batch_id is null
     or batch.claim_token <> p_claim_token
     or batch.status <> 'CLAIMED'
     or batch.claim_expires_at <= now() then
    raise exception 'RADAR_PROJECTION_STALE_CLAIM' using errcode = '40001';
  end if;

  select * into current_file
  from radar.projection_batch_files
  where batch_id = p_batch_id and path = p_path
  for update;

  if current_file.path is null then
    raise exception 'RADAR_PROJECTION_FILE_UNKNOWN' using errcode = 'P0002';
  end if;
  if current_file.state <> 'PENDING' and current_file.state <> p_state then
    raise exception 'RADAR_PROJECTION_FILE_RESULT_CONFLICT' using errcode = '23514';
  end if;

  update radar.projection_batch_files
  set state = p_state, result_ref = p_result_ref, updated_at = now()
  where batch_id = p_batch_id and path = p_path
  returning * into result;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_seed_lane_v1(p_identity_id text, p_branch text, p_projected_head_sha text)
 RETURNS radar.projection_lane_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  result radar.projection_lane_state;
begin
  if p_identity_id is null or btrim(p_identity_id) = ''
     or p_branch is null or btrim(p_branch) = '' then
    raise exception 'RADAR_PROJECTION_LANE_INVALID' using errcode = '22023';
  end if;
  if p_projected_head_sha is not null
     and p_projected_head_sha !~ '^[0-9a-f]{40}$' then
    raise exception 'RADAR_PROJECTION_HEAD_INVALID' using errcode = '22023';
  end if;

  insert into radar.projection_lane_state(identity_id, branch, projected_head_sha)
  values (p_identity_id, p_branch, p_projected_head_sha)
  on conflict (identity_id, branch) do nothing;

  select * into result
  from radar.projection_lane_state
  where identity_id = p_identity_id and branch = p_branch;

  if result.projected_head_sha is distinct from p_projected_head_sha then
    raise exception 'RADAR_PROJECTION_LANE_ALREADY_SEEDED' using errcode = '23514';
  end if;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.projection_set_control_cut_v1(p_identity_id text, p_branch text, p_control_sha text, p_topology_sha text)
 RETURNS radar.projection_lane_state
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  result radar.projection_lane_state;
begin
  if p_control_sha is null or p_control_sha !~ '^[0-9a-f]{40}$'
     or p_topology_sha is null or p_topology_sha !~ '^[0-9a-f]{40}$' then
    raise exception 'RADAR_PROJECTION_CONTROL_CUT_INVALID' using errcode = '22023';
  end if;

  update radar.projection_lane_state
  set control_sha = p_control_sha,
      topology_sha = p_topology_sha,
      updated_at = now()
  where identity_id = p_identity_id and branch = p_branch
  returning * into result;

  if result.identity_id is null then
    raise exception 'RADAR_PROJECTION_LANE_UNKNOWN' using errcode = 'P0002';
  end if;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.reconcile_bus_assignments_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  rec record;
  assignment_row record;
  predecessor_event_id bigint;
  new_event_id bigint;
  assignment_id_value text;
  workflow_id_value text;
  assignee_value text;
  event_value text;
  state_value text;
  predecessor_message_value text;
  authority_ref_value text;
  protected_text text;
  protected_value boolean;
  source_ref_value text;
  progress boolean;
  inserted_events integer := 0;
  inserted_assignments integer := 0;
  invalid_observations integer := 0;
  pending_observations integer := 0;
  conflict_observations integer := 0;
  allowed_states constant text[] := array[
    'DRAFTED','ASSIGNED','ACKNOWLEDGED','RUNNING','REVIEW_PENDING',
    'PAUSED_USAGE_EXHAUSTED','INTERRUPTED','HANDED_OFF','CHANGES_REQUESTED',
    'STOPPED','CONFIRMED','SUPERSEDED'
  ];
begin
  perform pg_advisory_xact_lock(hashtextextended('radar.reconcile_bus_assignments_v1', 0));

  -- Invalid explicit envelopes are durable observations, never guessed into
  -- assignment state. Ordinary messages without assignment_* keys are ignored.
  for rec in
    select m.*
    from radar.messages m
    where m.domain = 'chat_bus'
      and m.payload ?| array[
        'assignment_id','assignment_workflow_id','assignment_assignee',
        'assignment_event','assignment_state','assignment_predecessor_message_id',
        'assignment_authority_ref','assignment_protected_authority'
      ]
    order by m.created_at, m.message_id
  loop
    assignment_id_value := btrim(coalesce(rec.payload->>'assignment_id', ''));
    workflow_id_value := btrim(coalesce(rec.payload->>'assignment_workflow_id', ''));
    assignee_value := lower(btrim(coalesce(rec.payload->>'assignment_assignee', '')));
    event_value := upper(btrim(coalesce(rec.payload->>'assignment_event', '')));
    state_value := upper(btrim(coalesce(rec.payload->>'assignment_state', '')));
    predecessor_message_value := btrim(coalesce(rec.payload->>'assignment_predecessor_message_id', ''));
    authority_ref_value := nullif(btrim(coalesce(rec.payload->>'assignment_authority_ref', '')), '');
    protected_text := lower(btrim(coalesce(rec.payload->>'assignment_protected_authority', 'false')));
    source_ref_value := coalesce((rec.source_refs)[1], rec.message_id);

    if protected_text in ('true','yes','1') then
      protected_value := true;
    elsif protected_text in ('false','no','0','') then
      protected_value := false;
    else
      protected_value := null;
    end if;

    if assignment_id_value = ''
       or workflow_id_value = ''
       or assignee_value = ''
       or event_value = ''
       or state_value = ''
       or protected_value is null
       or not (state_value = any(allowed_states))
       or event_value <> state_value
       or (event_value = 'ASSIGNED' and predecessor_message_value <> '')
       or (event_value <> 'ASSIGNED' and predecessor_message_value = '')
       or (protected_value and authority_ref_value is null)
       or not exists (
         select 1 from radar.identities i where i.identity_id = assignee_value
       )
    then
      if not exists (
        select 1
        from radar.reconciliation_events e
        where e.code = 'ASSIGNMENT_ENVELOPE_INVALID'
          and e.detail->>'message_id' = rec.message_id
      ) then
        insert into radar.reconciliation_events(code, repair_class, source_ref, detail)
        values (
          'ASSIGNMENT_ENVELOPE_INVALID',
          'OBSERVATION_ONLY',
          source_ref_value,
          jsonb_build_object(
            'message_id', rec.message_id,
            'assignment_id', nullif(assignment_id_value, ''),
            'assignment_workflow_id', nullif(workflow_id_value, ''),
            'assignment_assignee', nullif(assignee_value, ''),
            'assignment_event', nullif(event_value, ''),
            'assignment_state', nullif(state_value, ''),
            'assignment_predecessor_message_id', nullif(predecessor_message_value, ''),
            'assignment_protected_authority', protected_text,
            'resolution', 'assignment_state_not_projected'
          )
        );
        invalid_observations := invalid_observations + 1;
      end if;
    end if;
  end loop;

  -- Iterate to a fixed point so out-of-arrival-order messages can become
  -- processable once their explicit predecessor has been projected.
  loop
    progress := false;

    for rec in
      select m.*
      from radar.messages m
      where m.domain = 'chat_bus'
        and m.payload ? 'assignment_id'
        and not exists (
          select 1
          from radar.reconciliation_events e
          where e.code = 'ASSIGNMENT_ENVELOPE_INVALID'
            and e.detail->>'message_id' = m.message_id
        )
      order by m.created_at, m.message_id
    loop
      assignment_id_value := btrim(coalesce(rec.payload->>'assignment_id', ''));
      workflow_id_value := btrim(coalesce(rec.payload->>'assignment_workflow_id', ''));
      assignee_value := lower(btrim(coalesce(rec.payload->>'assignment_assignee', '')));
      event_value := upper(btrim(coalesce(rec.payload->>'assignment_event', '')));
      state_value := upper(btrim(coalesce(rec.payload->>'assignment_state', '')));
      predecessor_message_value := btrim(coalesce(rec.payload->>'assignment_predecessor_message_id', ''));
      authority_ref_value := nullif(btrim(coalesce(rec.payload->>'assignment_authority_ref', '')), '');
      protected_text := lower(btrim(coalesce(rec.payload->>'assignment_protected_authority', 'false')));
      protected_value := protected_text in ('true','yes','1');
      source_ref_value := coalesce((rec.source_refs)[1], rec.message_id);

      if exists (
        select 1
        from radar.assignment_events ae
        where ae.assignment_id = assignment_id_value
          and ae.operation_id = rec.message_id
      ) then
        continue;
      end if;

      select a.* into assignment_row
      from radar.assignments a
      where a.assignment_id = assignment_id_value;

      if event_value = 'ASSIGNED' then
        if found then
          if not exists (
            select 1
            from radar.reconciliation_events e
            where e.code = 'ASSIGNMENT_EVENT_CONFLICT'
              and e.detail->>'message_id' = rec.message_id
          ) then
            insert into radar.reconciliation_events(code, repair_class, source_ref, detail)
            values (
              'ASSIGNMENT_EVENT_CONFLICT',
              'AMBIGUOUS_DURABLE_CONFLICT',
              source_ref_value,
              jsonb_build_object(
                'message_id', rec.message_id,
                'assignment_id', assignment_id_value,
                'reason', 'assignment_root_already_exists',
                'current_event_id', assignment_row.current_event_id,
                'resolution', 'state_not_advanced'
              )
            );
            conflict_observations := conflict_observations + 1;
          end if;
          continue;
        end if;

        insert into radar.assignments(
          assignment_id,
          workflow_id,
          current_state,
          authority_ref,
          protected_authority,
          current_event_id,
          assignee_identity_id,
          source_message_id,
          created_at,
          updated_at
        ) values (
          assignment_id_value,
          workflow_id_value,
          'DRAFTED',
          authority_ref_value,
          protected_value,
          null,
          assignee_value,
          rec.message_id,
          rec.created_at,
          rec.created_at
        );

        insert into radar.assignment_events(
          assignment_id,
          event_type,
          actor,
          from_state,
          to_state,
          predecessor_event_id,
          operation_id,
          receipt_sha256,
          detail,
          created_at
        ) values (
          assignment_id_value,
          event_value,
          rec.sender,
          'DRAFTED',
          state_value,
          null,
          rec.message_id,
          rec.content_hash,
          jsonb_build_object(
            'message_id', rec.message_id,
            'source_refs', to_jsonb(rec.source_refs),
            'assignee_identity_id', assignee_value,
            'workflow_id', workflow_id_value,
            'claim_basis', 'explicit_assignment_envelope_v1'
          ),
          rec.created_at
        )
        returning event_id into new_event_id;

        update radar.assignments
        set current_state = state_value,
            current_event_id = new_event_id,
            updated_at = greatest(updated_at, rec.created_at)
        where assignment_id = assignment_id_value;

        inserted_assignments := inserted_assignments + 1;
        inserted_events := inserted_events + 1;
        progress := true;
        continue;
      end if;

      if not found then
        continue;
      end if;

      -- V1 bindings are immutable inside one assignment chain. A change in
      -- workflow, assignee, or protected authority is a conflict, not a silent
      -- reassignment.
      if assignment_row.workflow_id <> workflow_id_value
         or assignment_row.assignee_identity_id is distinct from assignee_value
         or assignment_row.protected_authority <> protected_value
         or assignment_row.authority_ref is distinct from authority_ref_value
      then
        if not exists (
          select 1
          from radar.reconciliation_events e
          where e.code = 'ASSIGNMENT_EVENT_CONFLICT'
            and e.detail->>'message_id' = rec.message_id
        ) then
          insert into radar.reconciliation_events(code, repair_class, source_ref, detail)
          values (
            'ASSIGNMENT_EVENT_CONFLICT',
            'AMBIGUOUS_DURABLE_CONFLICT',
            source_ref_value,
            jsonb_build_object(
              'message_id', rec.message_id,
              'assignment_id', assignment_id_value,
              'reason', 'immutable_assignment_binding_mismatch',
              'resolution', 'state_not_advanced'
            )
          );
          conflict_observations := conflict_observations + 1;
        end if;
        continue;
      end if;

      select ae.event_id into predecessor_event_id
      from radar.assignment_events ae
      where ae.assignment_id = assignment_id_value
        and ae.operation_id = predecessor_message_value;

      if not found then
        continue;
      end if;

      if assignment_row.current_event_id is distinct from predecessor_event_id then
        if not exists (
          select 1
          from radar.reconciliation_events e
          where e.code = 'ASSIGNMENT_EVENT_CONFLICT'
            and e.detail->>'message_id' = rec.message_id
        ) then
          insert into radar.reconciliation_events(code, repair_class, source_ref, detail)
          values (
            'ASSIGNMENT_EVENT_CONFLICT',
            'AMBIGUOUS_DURABLE_CONFLICT',
            source_ref_value,
            jsonb_build_object(
              'message_id', rec.message_id,
              'assignment_id', assignment_id_value,
              'predecessor_message_id', predecessor_message_value,
              'predecessor_event_id', predecessor_event_id,
              'current_event_id', assignment_row.current_event_id,
              'reason', 'predecessor_is_not_current_assignment_event',
              'resolution', 'state_not_advanced'
            )
          );
          conflict_observations := conflict_observations + 1;
        end if;
        continue;
      end if;

      insert into radar.assignment_events(
        assignment_id,
        event_type,
        actor,
        from_state,
        to_state,
        predecessor_event_id,
        operation_id,
        receipt_sha256,
        detail,
        created_at
      ) values (
        assignment_id_value,
        event_value,
        rec.sender,
        assignment_row.current_state,
        state_value,
        predecessor_event_id,
        rec.message_id,
        rec.content_hash,
        jsonb_build_object(
          'message_id', rec.message_id,
          'source_refs', to_jsonb(rec.source_refs),
          'predecessor_message_id', predecessor_message_value,
          'claim_basis', 'explicit_assignment_envelope_v1'
        ),
        rec.created_at
      )
      on conflict (assignment_id, operation_id) do nothing
      returning event_id into new_event_id;

      if new_event_id is not null then
        update radar.assignments
        set current_state = state_value,
            current_event_id = new_event_id,
            updated_at = greatest(updated_at, rec.created_at)
        where assignment_id = assignment_id_value;

        inserted_events := inserted_events + 1;
        progress := true;
      end if;
      new_event_id := null;
    end loop;

    exit when not progress;
  end loop;

  -- Any otherwise valid successor still lacking an event after the fixed-point
  -- pass is waiting on an explicit predecessor/root that is not yet projected.
  for rec in
    select m.*
    from radar.messages m
    where m.domain = 'chat_bus'
      and m.payload ? 'assignment_id'
      and upper(btrim(coalesce(m.payload->>'assignment_event', ''))) <> 'ASSIGNED'
      and not exists (
        select 1 from radar.assignment_events ae
        where ae.assignment_id = btrim(m.payload->>'assignment_id')
          and ae.operation_id = m.message_id
      )
      and not exists (
        select 1 from radar.reconciliation_events e
        where e.detail->>'message_id' = m.message_id
          and e.code in ('ASSIGNMENT_ENVELOPE_INVALID','ASSIGNMENT_EVENT_CONFLICT')
      )
    order by m.created_at, m.message_id
  loop
    assignment_id_value := btrim(coalesce(rec.payload->>'assignment_id', ''));
    predecessor_message_value := btrim(coalesce(rec.payload->>'assignment_predecessor_message_id', ''));
    source_ref_value := coalesce((rec.source_refs)[1], rec.message_id);

    if not exists (
      select 1
      from radar.reconciliation_events e
      where e.code = 'ASSIGNMENT_EVENT_PENDING_PREDECESSOR'
        and e.detail->>'message_id' = rec.message_id
    ) then
      insert into radar.reconciliation_events(code, repair_class, source_ref, detail)
      values (
        'ASSIGNMENT_EVENT_PENDING_PREDECESSOR',
        'OBSERVATION_ONLY',
        source_ref_value,
        jsonb_build_object(
          'message_id', rec.message_id,
          'assignment_id', assignment_id_value,
          'predecessor_message_id', nullif(predecessor_message_value, ''),
          'resolution', 'await_explicit_predecessor_then_reconcile'
        )
      );
      pending_observations := pending_observations + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'assignments_inserted', inserted_assignments,
    'events_inserted', inserted_events,
    'invalid_observations_inserted', invalid_observations,
    'pending_observations_inserted', pending_observations,
    'conflict_observations_inserted', conflict_observations
  );
end;
$function$

CREATE OR REPLACE FUNCTION radar.touch_node(p_node_id uuid, p_status text DEFAULT 'ONLINE'::text)
 RETURNS radar.nodes
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  result radar.nodes;
begin
  if p_status not in ('ONLINE','IDLE','WORKING','WAITING_DEPENDENCY','DEGRADED','OFFLINE','PAUSED','ARCHIVED') then
    raise exception 'RADAR_INVALID_NODE_STATUS' using errcode = '22023';
  end if;

  update radar.nodes
  set
    status = p_status,
    last_heartbeat = now(),
    lease_expires_at = case
      when p_status in ('ONLINE','IDLE','WORKING','WAITING_DEPENDENCY','DEGRADED')
        then now() + interval '5 minutes'
      else null
    end,
    updated_at = now()
  where node_id = p_node_id
  returning * into result;

  if result.node_id is null then
    raise exception 'RADAR_UNKNOWN_NODE' using errcode = 'P0002';
  end if;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION radar.validate_subscription_node_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'radar'
AS $function$
declare
  node_identity text;
begin
  if new.node_id is null then
    if new.active then
      raise exception 'RADAR_ACTIVE_SUBSCRIPTION_NODE_REQUIRED' using errcode = '23514';
    end if;
    return new;
  end if;

  select n.identity_id
  into node_identity
  from radar.nodes n
  where n.node_id = new.node_id;

  if node_identity is null then
    raise exception 'RADAR_SUBSCRIPTION_NODE_UNKNOWN' using errcode = '23503';
  end if;

  if node_identity <> new.identity_id then
    raise exception 'RADAR_SUBSCRIPTION_NODE_IDENTITY_MISMATCH' using errcode = '23514';
  end if;

  return new;
end;
$function$
